# Generated by build.py from recipe.yml for recipe http-cut-a-download-off-halfway. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl rand -hex -out site/big.txt 2500000'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/', '--fault', '"drop;after-bytes=4000000"' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --max-time 30 -o dl/big.txt http://127.0.0.1:8080/big.txt || curl -sS --max-time 30 -C - -o dl/big.txt http://127.0.0.1:8080/big.txt } finally { Stop-Process $server0 }
